package org.casbin.jcasbin.effect;

import org.junit.Test;

import static org.junit.Assert.*;

public class PushTests {

    @Test
    public void testPushSomeWhereAllow() {
        DefaultStreamEffector effector = new DefaultStreamEffector("some(where (p_eft == allow))");

        // Initial state: effect should be false, done false
        assertFalse(effector.push(Effect.Indeterminate, 0, 2));
        assertFalse(effector.effect);

        // Push Indeterminate again
        assertFalse(effector.push(Effect.Indeterminate, 1, 2));
        assertFalse(effector.effect);

        // Reset for specific test
        effector = new DefaultStreamEffector("some(where (p_eft == allow))");

        // Push Allow: effect becomes true, done becomes true
        assertTrue(effector.push(Effect.Allow, 0, 2));
        assertTrue(effector.effect);
        assertEquals(0, effector.explainIndex);
        assertTrue(effector.done);

        // Push Deny: No change in this expression once Allow is found (though done is already true)
        // In actual stream, it wouldn't be called, but testing the logic:
        assertTrue(effector.push(Effect.Deny, 1, 2));
        assertTrue(effector.effect);
    }

    @Test
    public void testPushNotSomeWhereDeny() {
        DefaultStreamEffector effector = new DefaultStreamEffector("!some(where (p_eft == deny))");

        // Push Indeterminate: effect should be true (optimistic), done false
        assertFalse(effector.push(Effect.Indeterminate, 0, 2));
        assertTrue(effector.effect);

        // Push Allow: effect should still be true, done false
        assertFalse(effector.push(Effect.Allow, 1, 2));
        assertTrue(effector.effect);

        // Reset for Deny test
        effector = new DefaultStreamEffector("!some(where (p_eft == deny))");

        // Push Deny: effect becomes false, done becomes true
        assertTrue(effector.push(Effect.Deny, 0, 2));
        assertFalse(effector.effect);
        assertEquals(0, effector.explainIndex);
        assertTrue(effector.done);
    }

    @Test
    public void testPushAllowAndNotDeny() {
        DefaultStreamEffector effector = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");

        // Initial state
        assertFalse(effector.effect);

        // Push Allow
        assertFalse(effector.push(Effect.Allow, 0, 3));
        assertTrue(effector.effect);
        assertEquals(0, effector.explainIndex);
        assertFalse(effector.done);

        // Push Allow again
        assertFalse(effector.push(Effect.Allow, 1, 3));
        assertTrue(effector.effect);
        // Explain index should remain the first one (0)
        assertEquals(0, effector.explainIndex);
        assertFalse(effector.done);

        // Reset for Deny test
        effector = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");

        // Push Deny: effect false, done true
        assertTrue(effector.push(Effect.Deny, 1, 3));
        assertFalse(effector.effect);
        assertEquals(1, effector.explainIndex);
        assertTrue(effector.done);

        // Reset for Deny before Allow test
        effector = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");

        // Push Deny first
        assertTrue(effector.push(Effect.Deny, 0, 3));
        assertFalse(effector.effect);
        assertTrue(effector.done);
    }

    @Test
    public void testPushPriority() {
        String[] exprs = {"priority(p_eft) || deny", "subjectPriority(p_eft) || deny"};

        for (String expr : exprs) {
            DefaultStreamEffector effector = new DefaultStreamEffector(expr);

            // Push Indeterminate: effect remains false (default), done false
            assertFalse(effector.push(Effect.Indeterminate, 0, 2));
            assertFalse(effector.effect);

            // Push Allow: effect true, done true
            assertTrue(effector.push(Effect.Allow, 1, 2));
            assertTrue(effector.effect);
            assertEquals(1, effector.explainIndex);
            assertTrue(effector.done);

            // Reset for Deny test
            effector = new DefaultStreamEffector(expr);

            // Push Deny: effect false, done true
            assertTrue(effector.push(Effect.Deny, 0, 2));
            assertFalse(effector.effect);
            assertEquals(0, effector.explainIndex);
            assertTrue(effector.done);
        }
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testPushUnsupportedEffect() {
        DefaultStreamEffector effector = new DefaultStreamEffector("unknown_effect_expression");
        effector.push(Effect.Allow, 0, 1);
    }
}

