    @Test
    public void testRemoveMatchesDoesNotAffectOtherRoles() throws Exception {
        // Setup: A -> B, C -> B
        addMatchedBy(roleB, roleA);
        addMatched(roleA, roleB);

        addMatchedBy(roleB, roleC);
        addMatched(roleC, roleB);

        // Action: Remove matches for roleA
        invokeRemoveMatches(roleA);

        // Assert: A's matchedBy should be empty
        assertEquals(0, getMatchedByMap(roleA).size());

        // Assert: B should still contain A (since removeMatches only cleans up the 'roleB.matched' map via 'roleA.matchedBy' iterator logic)
        // Wait, let's trace the logic:
        // roleA.matchedBy has entry (roleA.name, roleA) -> No, roleA.matchedBy has entry ("roleB", roleB)? No.
        // Logic: role.matchedBy maps Key=ParentName, Value=ParentRole
        // role.matched maps Key=ChildName, Value=ChildRole

        // Correction based on usage in jCasbin:
        // If A has B, A.matched has B, B.matchedBy has A.
        // If we call removeMatches on A (the parent/holder):
        // Iterator over A.matchedBy. Wait, matchedBy is usually populated by addChild.
        // addChild adds to parent.roles AND parent.matched?
        // addChild adds to child.users AND child.matchedBy?

        // Let's assume standard relationship:
        // roleA.addRole(roleB) -> roleA.roles[roleB.name] = roleB; roleB.matchedBy[roleA.name] = roleA;
        // If we call removeMatches on roleB (the child):
        // Iterator over roleB.matchedBy (which contains roleA).
        // entry.getValue() is roleA.
        // roleA.matched.remove(roleB.name). 
        // iterator.remove().

        // Re-aligning test to this logic:
        Role parent = createRole("parent");
        Role child = createRole("child");

        // Link them
        addChild(parent, child); 
        // Now child.matchedBy has "parent" -> parent.
        // And parent.matched has "child" -> child. (Hypothetically, based on the code 'role.matched.remove(this.name)')

        assertTrue(getMatchedByMap(child).containsKey("parent"));

        invokeRemoveMatches(child);

        // child.matchedBy should be empty
        assertEquals(0, getMatchedByMap(child).size());
        // parent.matched should no longer contain child
        assertFalse(getMatchedMap(parent).containsKey("child"));
    }

    // Helper methods to access private fields and methods using Reflection

    private Role createRole(String name) throws Exception {
        try {
            java.lang.reflect.Constructor<Role> constructor = Role.class.getDeclaredConstructor(String.class);
            constructor.setAccessible(true);
            return constructor.newInstance(name);
        } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
            throw new RuntimeException("Failed to create Role instance via reflection", e);
        }
    }

    private Map<String, Role> getMatchedByMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matchedBy");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<String, Role> map = (Map<String, Role>) field.get(role);
        return map;
    }

    private Map<String, Role> getMatchedMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matched");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<String, Role> map = (Map<String, Role>) field.get(role);
        return map;
    }

    private void addMatchedBy(Role role, Role matchedByRole) throws Exception {
        Map<String, Role> map = getMatchedByMap(role);
        map.put(matchedByRole.name, matchedByRole);
    }

    private void addMatched(Role role, Role matchedRole) throws Exception {
        Map<String, Role> map = getMatchedMap(role);
        map.put(matchedRole.name, matchedRole);
    }

    // Simulates Role.addRole logic to set up the state correctly for removeMatches
    private void addChild(Role parent, Role child) throws Exception {
        Map<String, Role> parentRoles = (Map<String, Role>) getPrivateField(parent, "roles");
        parentRoles.put(child.name, child);

        Map<String, Role> childMatchedBy = getMatchedByMap(child);
        childMatchedBy.put(parent.name, parent);

        Map<String, Role> parentMatched = getMatchedMap(parent);
        parentMatched.put(child.name, child);
    }

    private Object getPrivateField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private void invokeRemoveMatches(Role role) throws Exception {
        Method method = Role.class.getDeclaredMethod("removeMatches");
        method.setAccessible(true);
        method.invoke(role);
    }
