    public void setUp() {
        domainManager = new DomainManager(10);
    }

    @Test
    public void testDeleteLinkWithoutDomain() {
        domainManager.addLink("u1", "g1");
        domainManager.addLink("g1", "g2");
        assertTrue(domainManager.hasLink("u1", "g1"));
        assertTrue(domainManager.hasLink("g1", "g2"));

        domainManager.deleteLink("u1", "g1");
        assertFalse(domainManager.hasLink("u1", "g1"));
        assertTrue(domainManager.hasLink("g1", "g2"));

        domainManager.deleteLink("g1", "g2");
        assertFalse(domainManager.hasLink("g1", "g2"));
    }

    @Test
    public void testDeleteLinkWithSingleDomain() {
        domainManager.addLink("u1", "g1", "domain1");
        domainManager.addLink("g1", "g2", "domain1");
        assertTrue(domainManager.hasLink("u1", "g1", "domain1"));
        assertTrue(domainManager.hasLink("g1", "g2", "domain1"));

        domainManager.deleteLink("u1", "g1", "domain1");
        assertFalse(domainManager.hasLink("u1", "g1", "domain1"));
        assertTrue(domainManager.hasLink("g1", "g2", "domain1"));

        domainManager.deleteLink("g1", "g2", "domain1");
        assertFalse(domainManager.hasLink("g1", "g2", "domain1"));
    }

    @Test
    public void testDeleteLinkWithMultipleDomains() {
        domainManager.addLink("u1", "g1", "domain1", "domain2");
        domainManager.addLink("g1", "g2", "domain1", "domain2");
        assertTrue(domainManager.hasLink("u1", "g1", "domain1", "domain2"));
        assertTrue(domainManager.hasLink("g1", "g2", "domain1", "domain2"));

        domainManager.deleteLink("u1", "g1", "domain1", "domain2");
        assertFalse(domainManager.hasLink("u1", "g1", "domain1", "domain2"));
        assertTrue(domainManager.hasLink("g1", "g2", "domain1", "domain2"));

        domainManager.deleteLink("g1", "g2", "domain1", "domain2");
        assertFalse(domainManager.hasLink("g1", "g2", "domain1", "domain2"));
    }

    @Test
    public void testDeleteLinkDoesNotAffectOtherDomains() {
        domainManager.addLink("u1", "g1", "domain1");
        domainManager.addLink("u1", "g1", "domain2");

        assertTrue(domainManager.hasLink("u1", "g1", "domain1"));
        assertTrue(domainManager.hasLink("u1", "g1", "domain2"));

        domainManager.deleteLink("u1", "g1", "domain1");

        assertFalse(domainManager.hasLink("u1", "g1", "domain1"));
        assertTrue(domainManager.hasLink("u1", "g1", "domain2"));
    }

    @Test
    public void testDeleteLinkWithDomainMatchingFunc() {
        BiPredicate<String, String> domainMatchingFunc = (d1, d2) -> d1.endsWith(d2);
        DomainManager matchingManager = new DomainManager(10, null, domainMatchingFunc);

        matchingManager.addLink("u1", "g1", "domain1");
        matchingManager.addLink("u1", "g1", "sub.domain1"); // This domain matches domain1
        matchingManager.addLink("u1", "g1", "domain2");

        assertTrue(matchingManager.hasLink("u1", "g1", "domain1"));
        assertTrue(matchingManager.hasLink("u1", "g1", "sub.domain1"));
        assertTrue(matchingManager.hasLink("u1", "g1", "domain2"));

        // Deleting from "domain1" should also delete from "sub.domain1" because of the matching function
        matchingManager.deleteLink("u1", "g1", "domain1");

        assertFalse(matchingManager.hasLink("u1", "g1", "domain1"));
        assertFalse(matchingManager.hasLink("u1", "g1", "sub.domain1"));
        assertTrue(matchingManager.hasLink("u1", "g1", "domain2"));
    }

    @Test
    public void testDeleteLinkWithDomainMatchingFuncReverseOrder() {
        BiPredicate<String, String> domainMatchingFunc = (d1, d2) -> d1.endsWith(d2);
        DomainManager matchingManager = new DomainManager(10, null, domainMatchingFunc);

        matchingManager.addLink("u1", "g1", "domain1");
        matchingManager.addLink("u1", "g1", "sub.domain1");

        // Add links to ensure rmMap is populated with 'domain1' before 'sub.domain1'
        matchingManager.addLink("u2", "g2", "domain1");
        matchingManager.addLink("u3", "g3", "sub.domain1");

        assertTrue(matchingManager.hasLink("u1", "g1", "domain1"));
        assertTrue(matchingManager.hasLink("u1", "g1", "sub.domain1"));

        // Delete from specific sub domain
        matchingManager.deleteLink("u1", "g1", "sub.domain1");

        assertTrue(matchingManager.hasLink("u1", "g1", "domain1"));
        assertFalse(matchingManager.hasLink("u1", "g1", "sub.domain1"));
    }

    @Test
    public void testDeleteLinkNonExistent() {
        // Should not throw exception
        domainManager.deleteLink("nonexistent", "nonexistent");
        domainManager.deleteLink("nonexistent", "nonexistent", "domain1");
    }
}
